// One authored learning path supplies classroom steps and complete reading.
// Booking examples are teacher-written; the E075–E085 resources retain their sources.
const ids = (requirement, ...numbers) => numbers.map(number => `S10.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows, title) => ({ headers, rows, ...(title ? { title } : {}) });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const recall = (title, body) => ({ title, body });

